def parenthesizeResults(nums, ops):
    memo = {}

    def go(i, j):
        if (i, j) in memo:
            return memo[(i, j)]
        if i == j:
            res = {nums[i]}
        else:
            res = set()
            for m in range(i, j):
                o = ops[m]
                for a in go(i, m):
                    for b in go(m + 1, j):
                        res.add(a + b if o == 0 else a - b if o == 1 else a * b)
        memo[(i, j)] = res
        return res

    return sorted(go(0, len(nums) - 1))
